floor_fn:
"""Replace any individual r, g, or b value less than threshold with 0.

    color: an (r, g, b) tuple
    threshold: a float

    """
def clip_black_by_channels(color: Any, threshold: Any) -> object {
    (r, g, b) = color;
    if (r < threshold) {
        r = 0;
    }
    if (g < threshold) {
        g = 0;
    }
    if (b < threshold) {
        b = 0;
    }
    return (r, g, b);
}

